func TestConcurrentAddAndRead(t *testing.T) {
	r := New(2500 * time.Millisecond) // non-integer-second window
	const writers = 8
	const perWriter = 200

	var wg sync.WaitGroup
	// Readers run for the whole duration; every snapshot they see must be
	// internally consistent (Min <= Max, Count > 0 in every bucket).
	stop := make(chan struct{})
	for i := 0; i < 2; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for {
				select {
				case <-stop:
					return
				default:
				}
				for _, w := range r.Windows() {
					if w.Count <= 0 || w.Min > w.Max {
						t.Errorf("inconsistent snapshot: %+v", w)
					}
				}
				if _, ok := r.Window(time.Unix(0, 0)); ok {
					// Copy must stay valid while writes continue.
					if _, ok2 := r.Window(time.Unix(0, 0)); !ok2 {
						t.Error("window vanished between reads")
					}
				}
			}
		}()
	}

	// Each writer files perWriter samples at ever-increasing instants, all
	// landing in distinct windows per writer offset so no sample is
	// rejected.
	base := int64(0)
	for w := 0; w < writers; w++ {
		wg.Add(1)
		go func(w int) {
			defer wg.Done()
			for i := 0; i < perWriter; i++ {
				at := time.Unix(0, base+int64(i)*int64(2500*time.Millisecond)+int64(w))
				if err := r.Add(at, float64(w)); err != nil {
					t.Errorf("Add: %v", err)
				}
			}
		}(w)
	}
	// Wait for writers, then stop readers.
	done := make(chan struct{})
	go func() {
		// Wait only for the writer goroutines: poll until the total count
		// reaches writers*perWriter.
		for {
			var total int64
			for _, w := range r.Windows() {
				total += w.Count
			}
			if total == writers*perWriter {
				close(done)
				return
			}
		}
	}()
	<-done
	close(stop)
	wg.Wait()

	var total int64
	for _, w := range r.Windows() {
		total += w.Count
	}
	if total != writers*perWriter {
		t.Fatalf("total count = %d, want %d", total, writers*perWriter)
	}
}

