	var readers sync.WaitGroup
	for i := 0; i < 2; i++ {
		readers.Add(1)
		go func() {
			defer readers.Done()
			for {
				select {
				case <-stop:
					return
				default:
				}
				for _, w := range r.Windows() {
					if w.Count <= 0 || w.Min > w.Max {
						t.Errorf("inconsistent snapshot: %+v", w)
					}
				}
				r.Window(time.Unix(0, 0))
			}
		}()
	}

